class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        def rob_helper(sub):
            rob1, rob2 = 0, 0
            for n in sub:
                new_rob = max(rob1 + n, rob2)
                rob1 = rob2
                rob2 = new_rob
            return rob2
        return max(rob_helper(nums[:-1]), rob_helper(nums[1:]))

reference_solution.javascript:
function rob(nums) {
    if (nums.length === 1) return nums[0];
    function robHelper(sub) {
        let rob1 = 0, rob2 = 0;
        for (const n of sub) {
            const newRob = Math.max(rob1 + n, rob2);
            rob1 = rob2;
            rob2 = newRob;
        }
        return rob2;
    }
    return Math.max(robHelper(nums.slice(0, -1)), robHelper(nums.slice(1)));
}
